#!/bin/sh
# Generated by `cargo run -p avianlink-sim --bin netem-gen` from the
# `geo_satellite` simulator profile (MTU 1200). Do not edit; regenerate.
# Usage (as root, Linux): geo_satellite.sh DEV [DEV...]
# Apply on every interface whose egress should be impaired, e.g. both
# interfaces of a box routing between two hosts. Run the CLI with
# `--profile geo_satellite` so the engine uses the same MTU and budget.
set -eu
[ $# -ge 1 ] || { echo "usage: $0 DEV [DEV...]" >&2; exit 2; }
NETEM="delay 295ms 20ms loss gemodel 0.5% 30% 50% 0.5% corrupt 0.1% rate 64000bit limit 625"
for dev in "$@"; do tc qdisc replace dev "$dev" root netem $NETEM; done
# Outages: up 7200 s, down 120 s on average, all devices together.
NETEM_DOWN="delay 295ms 20ms loss 100% corrupt 0.1% rate 64000bit limit 625"
# Exponential durations, seeded from /dev/urandom.
draw() { awk -v m="$1" -v s="$(od -An -N4 -tu4 /dev/urandom)" \
  'BEGIN { srand(s); r = rand(); if (r < 1e-9) r = 1e-9; printf "%d", -log(r) * m + 1 }'; }
trap 'for dev in "$@"; do tc qdisc del dev "$dev" root 2>/dev/null || true; done' EXIT INT TERM
echo "netem: $NETEM (with outages; Ctrl-C to stop and clear)"
while :; do
  sleep "$(draw 7200)"
  for dev in "$@"; do tc qdisc change dev "$dev" root netem $NETEM_DOWN; done
  echo "$(date +%T) link down"
  sleep "$(draw 120)"
  for dev in "$@"; do tc qdisc change dev "$dev" root netem $NETEM; done
  echo "$(date +%T) link up"
done
